<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Second {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        String st = br.readLine();
        char[] c = st.toCharArray();
        int maxLen = 0, bracketCount = 0;
        StringBuilder sb = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();

        for (int i = 0; i < n; i++) {
            if (c[i] == '(') {
                sb.append("_");
                i++;
                while (i < n && c[i] != ')') {
                    sb2.append(c[i]);
                    i++;
                }
                sb2.append("_");
            } else {
                sb.append(c[i]);
            }
        }

        String[] segments = sb.toString().split("_");
        for (String segment : segments) {
            maxLen = Math.max(maxLen, segment.length());
        }

        String[] brackets = sb2.toString().split("_");
        for (String b : brackets) {
            if (b.length() > 0) {
                bracketCount++;
            }
        }

        System.out.println(maxLen + " " + bracketCount);
        br.close();
    }
}
